SELECT COUNT(*) AS customers_in_goiania
FROM customers
WHERE lower(customer_city) = 'goiania';

SELECT COUNT(*) AS customers_in_parana
FROM customers
WHERE customer_state = 'PR';

SELECT COUNT(DISTINCT order_id) AS order_count_last_90_days
FROM orders
WHERE order_purchase_timestamp >= (SELECT MAX(order_purchase_timestamp) FROM orders) - INTERVAL '90 days';

SELECT COUNT(*) AS order_count
FROM orders
WHERE order_purchase_timestamp >= (SELECT MAX(order_purchase_timestamp) FROM orders) - INTERVAL 60 DAY;
